  settings_search_idx_capped: 'Limiet bereikt: Xenon voegt geen bestanden meer toe, dus de zoekfunctie ziet ze niet allemaal. Haal een map uit de lijst hierboven, of geef specifieke mappen op in plaats van hele schijven.',
