  settings_search_idx_near_cap: 'De index zit op {pct}% van zijn limiet ({max} bestanden): groeien ze verder, dan voegt Xenon er geen meer toe en ziet de zoekfunctie ze niet allemaal. Haal een map uit de lijst hierboven, of geef specifieke mappen op in plaats van hele schijven.',
  settings_search_idx_fda: 'macOS heeft Xenon de volledige schijftoegang ontnomen. Dat gebeurt bij elke update, omdat de toestemming aan de handtekening van de app hangt. Zolang die ontbreekt indexeert Xenon je thuismap niet: anders zou macOS bij elke ronde toestemming vragen voor Bureaublad, Documenten, Downloads, Foto\'s en Muziek. Zet hem terug aan via Systeeminstellingen → Privacy en beveiliging → Volledige schijftoegang: haal Xenon uit de lijst en voeg hem opnieuw toe.',
  disk_fda_title: 'macOS heeft een toestemming van Xenon ingetrokken',
  disk_fda_text: 'Na elke update ontneemt macOS Xenon de volledige schijftoegang. Zonder die toegang blijven de schijfkaart en de zoekfunctie leeg. Zet hem terug aan: haal Xenon uit de lijst en voeg hem opnieuw toe.',
