  settings_hybrid_gpu_pause: 'Animaties beperken bij hybride GPU',
  settings_hybrid_gpu_pause_hint: 'Deze pc heeft twee videokaarten en Xenon tekent op de geïntegreerde, die minder ruimte heeft: de aurora, het raster, de bewegende achtergrond en kleine animaties staan stil, grafieken springen in plaats van te glijden en boven een video of GIF is de Ambient-klok vol in plaats van glas. Zet het uit om alles te houden, ten koste van wat beelden',
  settings_bg_code_frozen_gpu: 'Op deze pc stopt de achtergrond na een paar seconden: hij heeft twee videokaarten en Xenon tekent op de geïntegreerde. Het ligt niet aan jouw code. Je kunt het aanpassen met “Animaties beperken bij hybride GPU”, onder Weergave, Oppervlak.',
