  'remote.intro_p1': 'Hiermee open je het bureaublad van je pc vanaf een smartphone of tablet via je eigen privé-Tailscale-netwerk (peer-to-peer-VPN). Videostreaming wordt verzorgd door Sunshine; de gratis Moonlight-client draait op je telefoon.',
