  surface_mode_both: 'Op de telefoon en ook op deze pc',
  surface_mode_both_hint: 'Het dashboard opent op de gekoppelde telefoon en blijft ook hier openen.',
  ra_guide_open: 'Stapsgewijze uitleg',
  ra_guide_title: 'De telefoon instellen, stap voor stap',
  ra_guide_close: 'Uitleg sluiten',
  ra_guide_sub: 'Stap 1 tot 3 zetten het dashboard thuis op je telefoon. De rest is alleen nodig als je het ook onderweg wilt.',
  ra_guide_group_home: 'Thuis, op je eigen wifi',
  ra_guide_group_away: 'Onderweg (optioneel)',
  ra_guide_ack: 'Gedaan',
  ra_guide_undo: 'Nog niet',
  ra_guide_s1: 'Zet toegang vanaf andere apparaten aan',
  ra_guide_s1_body: 'Het staat uit tot jij het aanzet. Zolang het uit staat, antwoordt Xenon alleen deze pc.',
  ra_guide_s2: 'Richt je telefoon op de QR-code',
  ra_guide_s2_body: 'De code is een uitnodiging, geen wachtwoord: hij geldt drie minuten en werkt niet meer na een paar verkeerde pogingen. Het dashboard opent in de browser van de telefoon. Op de telefoon hoef je niets te installeren.',
  ra_guide_s2_wait: 'Beschikbaar zodra de schakelaar hierboven aan staat.',
  ra_guide_s3: 'Zet het op het beginscherm van de telefoon',
  ra_guide_s3_body: 'Op de iPhone tik je op Deel en daarna op Zet op beginscherm. Op Android biedt Chrome aan het te installeren. Xenon opent dan met een eigen pictogram, schermvullend, en daar werken de microfoon en meldingen.',
  ra_guide_s4: 'Zet het veilige adres aan',
  ra_guide_s4_body: 'Dit geeft deze pc een eigen naam die overal werkt, over een versleutelde verbinding. Het gebruikt Tailscale, dat gratis is, en Xenon installeert het en meldt zich voor je aan. Je maakt geen account bij Xenon.',
  ra_guide_s5: 'Zet HTTPS-certificaten aan in je Tailscale-account',
  ra_guide_s5_body: 'Dit is de enige stap die Xenon niet voor je kan doen. Open de Tailscale-beheerconsole, scroll naar HTTPS Certificates en druk op Enable. Het is gratis bij elk pakket. Kom daarna terug: Xenon heeft door staan wachten.',
  ra_guide_s6: 'Installeer Tailscale op de telefoon, hetzelfde account',
  ra_guide_s6_body: 'Haal het uit de App Store of Google Play, meld je aan met hetzelfde account dat je net gebruikte, en zet de schakelaar aan. Dit is de stap die iedereen vergeet. Ontbreekt hij, dan zegt de telefoon dat hij het adres helemaal niet kan openen: er is niets stuk, dat adres bestaat alleen binnen je eigen netwerk.',
  ra_guide_s7: 'Koppel de telefoon opnieuw op het nieuwe adres',
  ra_guide_s7_body: 'Druk in stap 2 op Apparaat toevoegen en scan opnieuw. De browser bindt een koppeling aan het adres waarop hij is gemaakt, dus een telefoon die thuis is gekoppeld, is dat niet op het veilige adres. Daarna heb je alleen het nieuwe adres nodig, thuis en onderweg.',
  ra_guide_done_title: 'Het instellen is klaar',
  ra_guide_done_body: 'Je telefoon is gekoppeld. Nog één ding: moet Xenon ook op deze pc blijven openen?',
  ra_guide_keep: 'Hier ook houden',
  ra_guide_hide: 'Xenon op deze pc verbergen',
  ra_guide_hide_note: 'Verbergen zorgt dat Xenon niet meer op deze pc opent, ook niet bij aanmelden. Het draait op de achtergrond door, dus de telefoon blijft werken. Je haalt het venster terug via het Xenon-pictogram naast de klok, of via Instellingen en dan Scherm.',
  ra_guide_hide_browser: 'Dit is het dashboard in een browser, dus er is geen venster om te verbergen. In de Xenon-app kun je ook kiezen dat het niet meer op deze pc opent.',
  settings_stack: 'Indeling van de tegels',
